package com.personal.assistant.module.search.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.search.dto.SearchResult;import com.personal.assistant.module.search.mapper.GlobalSearchMapper;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/search")public class GlobalSearchController{private final GlobalSearchMapper mapper;public GlobalSearchController(GlobalSearchMapper mapper){this.mapper=mapper;}@GetMapping public ApiResponse<List<SearchResult>>search(@RequestParam String keyword){if(keyword==null||keyword.trim().length()<2)return ApiResponse.success(List.of());return ApiResponse.success(mapper.search(SecurityContextHelper.currentUserId(),keyword.trim()));}}
